<script setup lang="ts">
import { ref,computed,onMounted,onBeforeUnmount,watch } from 'vue'
import { useRouter } from 'vue-router'
import { api,post } from '../api'
import { state,prepareEncouragement,encourage,encouragePrecision,toggleVoice } from '../store'
import Icon from '../components/Icon.vue'
import { stopEncouragementAudio } from '../audio'
import AnnotationCanvas from '../components/AnnotationCanvas.vue'
import QuestionInput from '../components/QuestionInput.vue'
import PrecisionReward from '../components/PrecisionReward.vue'
const precisionReward=ref(false),showStandard=ref(false),standardAnswer=ref<any>()
const router=useRouter(),step=ref(0),run=ref<any>(),error=ref(''),busy=ref(false),answer=ref<any>({}),guided=ref<any>({}),found=ref(false),feedback=ref<any>(),diagnosticIndex=ref(0),diagnosticAnswer=ref<any>({})
let alive=true,viewRevision=0
function isCurrent(revision:number){return alive&&revision===viewRevision}
function invalidateView(){viewRevision++;stopEncouragementAudio();busy.value=false;precisionReward.value=false;showStandard.value=false;standardAnswer.value=undefined}
watch([step,diagnosticIndex],invalidateView,{flush:'sync'})
onBeforeUnmount(()=>{alive=false;invalidateView()})
const stages=['欢迎','认识标注','找到目标','学习框选','学习标签','独立完成','即时反馈','学情诊断','开始成长']
const current= computed(()=>run.value?.questions[step.value<=4?0:1])
function restoreRun(started:any){run.value=started;const independent=started.questions[1],saved=started.question_feedback?.[independent.id];if(saved){answer.value=JSON.parse(JSON.stringify(started.answers[independent.id]));feedback.value=saved;step.value=6}}
onMounted(async()=>{try{const started=await post('/onboarding/start');if(alive)restoreRun(started)}catch(e){if(alive)error.value=(e as Error).message}})
function next(){error.value='';step.value++}
function spot(p:number[]){const b=current.value.guide_box;found.value=p[0]>=b[0]&&p[0]<=b[0]+b[2]&&p[1]>=b[1]&&p[1]<=b[1]+b[3];if(found.value){error.value=''}else error.value='再观察一下，试着点击任务指定的目标。'}
async function submitGuide(){if(busy.value)return;prepareEncouragement();const revision=viewRevision;busy.value=true;error.value='';try{const r=await post(`/runs/${run.value.id}/answer`,{question_id:run.value.questions[0].id,answer:JSON.parse(JSON.stringify(guided.value))});if(!isCurrent(revision))return;if(r.result.correct){next();void encourage()}else error.value='标签或边界还可以更准确。返回上一步调整边界，再选中目标标签。'}catch(e){if(isCurrent(revision))error.value=(e as Error).message}finally{if(isCurrent(revision))busy.value=false}}
async function submitIndependent(){if(busy.value)return;prepareEncouragement();const revision=viewRevision,submittedAnswer=JSON.parse(JSON.stringify(answer.value));busy.value=true;error.value='';try{const r=await post(`/runs/${run.value.id}/answer`,{question_id:current.value.id,answer:submittedAnswer});if(!isCurrent(revision))return;answer.value=submittedAnswer;feedback.value={...r.result,wrong_attempts:r.wrong_attempts||0,can_view_standard:r.can_view_standard===true};step.value=6;if(typeof r.result.iou==='number'&&r.result.iou>.9){precisionReward.value=true;void encouragePrecision()}else if(r.result.correct)void encourage()}catch(e){if(isCurrent(revision))error.value=(e as Error).message}finally{if(isCurrent(revision))busy.value=false}}
async function viewStandard(){if(busy.value||!feedback.value?.can_view_standard)return;const revision=viewRevision;busy.value=true;error.value='';try{const result=await api(`/runs/${run.value.id}/questions/${current.value.id}/standard-answer`);if(!isCurrent(revision))return;standardAnswer.value=result.standard_answer;showStandard.value=true;stopEncouragementAudio();precisionReward.value=false}catch(e){if(isCurrent(revision))error.value=(e as Error).message}finally{if(isCurrent(revision))busy.value=false}}
function retryIndependent(){if(busy.value)return;answer.value={boxes:[]};feedback.value=undefined;error.value='';step.value=5}
async function submitDiagnostic(){if(busy.value)return;const revision=viewRevision;busy.value=true;error.value='';try{await post(`/runs/${run.value.id}/answer`,{question_id:run.value.questions[diagnosticIndex.value+2].id,answer:JSON.parse(JSON.stringify(diagnosticAnswer.value))});if(!isCurrent(revision))return;diagnosticAnswer.value={};if(diagnosticIndex.value<2)diagnosticIndex.value++;else step.value=8}catch(e){if(isCurrent(revision))error.value=(e as Error).message}finally{if(isCurrent(revision))busy.value=false}}
async function finish(){if(busy.value)return;const revision=viewRevision;busy.value=true;try{const user=await post('/onboarding/complete',{run_id:run.value.id});if(!isCurrent(revision))return;state.user=user;router.push('/')}catch(e){if(isCurrent(revision))error.value=(e as Error).message}finally{if(isCurrent(revision))busy.value=false}}
const hasBox=computed(()=>guided.value?.boxes?.some((b:any)=>b.box[2]>.02&&b.box[3]>.02));const hasLabel=computed(()=>hasBox.value&&guided.value.boxes.every((b:any)=>b.label))
</script>
<template><div class="onboarding-page"><PrecisionReward v-if="precisionReward" @done="precisionReward=false"/><header class="learning-header"><a href="/" class="brand"><img src="/favicon.svg" alt=""><span>智基<span class="brand-dot">.</span></span></a><div class="onboarding-progress"><div class="progress-line"><span :style="{width:((step+1)/9*100)+'%'}"></span></div><span>{{step+1}} / 9</span></div><button class="icon-button" @click="toggleVoice" :disabled="state.voiceSaving" :aria-pressed="!!state.user?.voice" :aria-label="state.user?.voice?'关闭答对鼓励':'开启答对鼓励'"><Icon :name="state.user?.voice?'Volume2':'VolumeX'"/></button></header><div v-if="!run" class="loading-state"><span v-if="error">{{error}}</span><template v-else><Icon name="LoaderCircle" class="spin"/>准备你的第一次标注体验…</template></div><div v-else class="onboarding-body" :class="{wide:step>=2&&step<=6}" :key="step"><span class="onboarding-step">{{stages[step]}}</span><template v-if="step===0"><img src="/mentor-v2.png" class="welcome-mentor" alt="挥手的小基"><h1>嗨，我是小基。<br>一起教会 AI 看懂世界吧！</h1><p>不需要任何基础。跟着我动手试一试，<br>几分钟后，你就能完成自己的第一枚标注。</p><div class="onboarding-tags"><span><Icon name="MousePointer2" :size="17"/>边做边学</span><span><Icon name="MessageCircle" :size="17"/>即时反馈</span><span><Icon name="RotateCcw" :size="17"/>放心尝试</span></div></template><template v-if="step===1"><div class="concept-flow"><span><Icon name="ScanEye" :size="44"/>你看见目标</span><Icon name="ArrowRight" :size="25"/><span class="focus"><Icon name="SquareDashed" :size="44"/>为目标做标记</span><Icon name="ArrowRight" :size="25"/><span><Icon name="Sparkles" :size="44"/>AI 从中学习</span></div><h1>你看得懂，AI 还需要学习。</h1><p>当你告诉 AI “这里有一辆汽车”，<br>并把汽车的位置标出来，你就在做<strong>数据标注</strong>。</p><div class="concept-example">自动驾驶识别行人、工厂发现缺陷、客服理解文字，<br>背后都离不开清晰、准确的标注。</div></template><template v-if="step===2"><h1>先找到它，不急着画框。</h1><p>在图片中，点击<strong>最大的{{current.guide_label}}</strong>。<br>标注的第一步，是先看清目标。</p><AnnotationCanvas :question="current" :model-value="{}" find-only @spot="spot"/><div v-if="found" class="inline-success"><Icon name="Check"/>找到啦！现在我们知道该标哪里了。</div></template><template v-if="step===3"><h1>给目标，画一个刚刚好的框。</h1><p>从目标的左上角按住鼠标，拖到右下角再松开。<br>尽量贴合边缘，也别漏掉任何部分。</p><AnnotationCanvas :question="current" v-model="guided" guide :labels-visible="false"/></template><template v-if="step===4"><h1>这个目标，叫什么？</h1><p>框告诉 AI “在哪里”，标签告诉 AI “是什么”。<br>点选下面与目标对应的标签。</p><AnnotationCanvas :question="current" v-model="guided" guide/></template><template v-if="step===5"><h1>这一次，你来独立完成。</h1><p>{{current.title}}<br>看图片 → 找目标 → 标出来 → 选标签 → 提交。</p><AnnotationCanvas :question="current" v-model="answer" :disabled="busy"/></template><template v-if="step===6"><div class="feedback-symbol" :class="{retry:!feedback.correct}"><Icon :name="feedback.correct?'Check':'RotateCcw'" :size="50"/></div><h1>{{feedback.correct?'你的第一枚标注，完成了！':'再调整一点，就更好了。'}}</h1><p>{{feedback.correct?'从看见目标，到告诉 AI 它是什么，你已经掌握了完整流程。':feedback.feedback}}</p><div class="feedback-iou"><span>区域重合度</span><b>{{Math.round((feedback.iou||0)*100)}}<small>%</small></b><span>{{feedback.correct?'边界与标签都通过了检查':'对照目标边缘，检查框是否过大或过小'}}</span></div><AnnotationCanvas :question="current" :model-value="answer" disabled :standard="showStandard?standardAnswer:undefined"/><div class="onboarding-answer-controls"><button v-if="feedback.can_view_standard&&!showStandard" class="btn outline small" :disabled="busy" @click="viewStandard"><Icon name="ScanEye" :size="17"/>查看标准答案</button><p v-if="showStandard" role="status">正在查看标准答案，标注已锁定。点击“再试一次”后清空并重新标注。</p><p v-else-if="!feedback.can_view_standard">本题连续答错 {{feedback.wrong_attempts||0}} 次；答对或连续答错 3 次后，可自行查看标准答案。</p></div><div v-if="!feedback.correct" class="concept-example">每一次调整都在帮助你学会观察。<br>点击“再试一次”，用刚刚学到的方法改进标注。</div></template><template v-if="step===7"><span class="pill purple">诊断 {{diagnosticIndex+1}} / 3</span><h1>最后，看看你已经知道什么。</h1><p>这是起点，不是考试。我们会用它为你推荐下一步。</p><h2 class="diagnostic-title">{{run.questions[diagnosticIndex+2].title}}</h2><QuestionInput :key="diagnosticIndex" :question="run.questions[diagnosticIndex+2]" v-model="diagnosticAnswer"/></template><template v-if="step===8"><img src="/mentor-v2.png" class="welcome-mentor small" alt="小基"><span class="pill lime"><Icon name="Check" :size="14"/>入门体验已完成</span><h1>准备好了，向真本领出发。</h1><p>接下来，从基础认知开始，逐步走向真实岗位。</p><div class="onboarding-tags"><span><Icon name="ScanLine"/>第一枚标注</span><span><Icon name="Target"/>个性化学习路径</span></div></template><div v-if="error" class="error-message" role="alert">{{error}}</div></div><footer v-if="run" class="learning-footer"><div><button v-if="step>0&&step<6" class="text-button" :disabled="busy" @click="step--;error='' "><Icon name="ArrowLeft" :size="16"/>上一步</button><span v-else class="footer-encouragement">每一个高手，都从第一次尝试开始。</span><button v-if="step<=3" class="btn green" @click="next" :disabled="step===2&&!found||step===3&&!hasBox">{{step===0?'好，开始吧':'继续'}}<Icon name="ArrowRight" :size="18"/></button><button v-if="step===4" class="btn green" @click="submitGuide" :disabled="busy||!hasLabel">检查我的标注<Icon name="Check" :size="18"/></button><button v-if="step===5" class="btn green" @click="submitIndependent" :disabled="busy||!answer.boxes?.length||!answer.boxes?.every((b:any)=>b.label)">提交标注<Icon name="Check" :size="18"/></button><div v-if="step===6" class="exercise-actions"><button class="btn outline" :disabled="busy" @click="retryIndependent">再试一次<Icon name="RotateCcw" :size="18"/></button><button v-if="feedback.correct" class="btn green" :disabled="busy" @click="step=7">继续了解自己<Icon name="ArrowRight" :size="18"/></button></div><button v-if="step===7" class="btn green" @click="submitDiagnostic" :disabled="busy||!diagnosticAnswer.value">{{diagnosticIndex<2?'下一题':'看看我的起点'}}<Icon name="ArrowRight" :size="18"/></button><button v-if="step===8" class="btn green" @click="finish" :disabled="busy">{{busy?'保存中…':'进入正式训练'}}<Icon name="ArrowRight" :size="18"/></button></div></footer></div></template>

<style scoped>.onboarding-answer-controls{display:flex;flex-direction:column;align-items:center;gap:12px;margin-top:18px}.onboarding-answer-controls p{font-size:13px;color:#697568;line-height:1.8;margin:0}@media(max-width:760px){.onboarding-page .learning-footer:has(.exercise-actions) .footer-encouragement{display:none}.onboarding-page .learning-footer:has(.exercise-actions)>div{justify-content:flex-end}}</style>
